def decode(data):
    r = _Reader(bytes(data))
    r.ws()
    v = _decode_resolveresult(r)
    r.ws()
    if r.pos < len(r.buf):
        raise r.refuse("trailing_bytes")
    return v


# REFUSALS is in the order two of them are chosen between.

REFUSALS = ["malformed", "bad_string", "number_spelling", "wrong_type", "depth_exceeded", "duplicate_key", "duplicate_field", "unknown_field", "missing_field", "bad_enum", "trailing_bytes"]


def refusal_rank(word):
    return REFUSALS.index(word) if word in REFUSALS else -1


class DispatchError(ValueError):
    def __init__(self, code):
        super().__init__(code)
        self.code = code


def _service_decode(decoder, frame, depth=0):
    if not isinstance(frame, (bytes, bytearray, memoryview)):
        raise TypeError("transport frame must be bytes")
    r = _Reader(bytes(frame))
    r.depth = depth
    r.ws()
    value = decoder(r)
    r.ws()
    if r.pos != len(r.buf):
        raise r.refuse("trailing_bytes")
    return value


def _service_encode(encoder, value, depth):
    out = bytearray()
    try:
        encoder(out, value, depth)
    except UnicodeError:
        raise Refusal("bad_string", 0) from None
    return bytes(out)


def _service_request(service, method, arguments):
    v = OAServiceFrame(version=1, service=service, method=method, arguments=arguments)
    frame = _service_encode(enc_oaserviceframe, v, 0)
    _service_decode(_decode_oaserviceframe, frame)
    return frame


def _service_check(kind, value, depth=0):
    # Python coercions must not silently change typed service arguments.
    if depth >= _DEPTH_LIMIT and (kind.startswith(("list<", "map<")) or kind in _SERVICE_RECORDS):
        raise Refusal("depth_exceeded", 0)
    if kind == "string":
        valid = type(value) is str
    elif kind in ("i32", "i64"):
        valid = type(value) is int
        if valid:
            limit = 1 << (31 if kind == "i32" else 63)
            if not -limit <= value < limit:
                raise Refusal("number_spelling", 0)
    elif kind == "bool":
        valid = type(value) is bool
    elif kind == "json":
        valid = isinstance(value, (str, bytes, bytearray, memoryview))
    elif kind.startswith("list<"):
        valid = type(value) is list
        if valid:
            for item in value:
                _service_check(kind[5:-1], item, depth + 1)
    elif kind.startswith("map<string,"):
        valid = type(value) is dict
        if valid:
            for key, item in value.items():
                _service_check("string", key, depth + 1)
                _service_check(kind[11:-1], item, depth + 1)
    else:
        cls, fields = _SERVICE_RECORDS[kind]
        valid = isinstance(value, cls)
        if valid:
            for name, field_kind, omit in fields:
                if not hasattr(value, name):
                    raise Refusal("missing_field", 0)
                item = getattr(value, name)
                if omit == "absent" and item is None:
                    continue
                _service_check(field_kind, item, depth + 1)
    if not valid:
        raise Refusal("wrong_type", 0)


class ServiceError(Exception):
    def __init__(self, code, message=""):
        super().__init__(message if message else code)
        self.code = code
        self.message = message


def _service_response(frame, service, method):
    reply = _service_decode(_decode_oaservicereply, frame)
    if reply.version != 1:
        raise DispatchError("unknown_version")
    if reply.service != service or reply.method != method:
        raise DispatchError("mismatched_response")
    if not reply.ok:
        error = _service_decode(_decode_oaserviceerror, reply.payload, 1)
        if not error.code:
            raise DispatchError("invalid_error")
        raise ServiceError(error.code, error.message)
    return reply.payload

_SERVICE_RECORDS = {
    "ResolveRequest": (ResolveRequest, [("capability","string","never"),("contracts","list<string>","never"),("guarantees","list<string>","never"),("scope","string","never"),]),
    "ServiceReference": (ServiceReference, [("provider","string","never"),("capability","string","never"),("contract","string","never"),("guarantees","list<string>","never"),("scope","string","never"),("transport","string","never"),("endpoint","string","never"),]),
    "ResolveResult": (ResolveResult, [("status","string","never"),("reference","ServiceReference","absent"),]),
    "BootstrapObservation": (BootstrapObservation, [("state","string","never"),("detail","string","absent"),]),
    "CapabilityObservation": (CapabilityObservation, [("request","ResolveRequest","never"),("result","ResolveResult","absent"),]),
    "RuntimeObservation": (RuntimeObservation, [("bootstrap","BootstrapObservation","never"),("capabilities","list<CapabilityObservation>","never"),]),
    "OAResolverResolveArguments": (OAResolverResolveArguments, [("request","ResolveRequest","never"),]),
    "OAServiceFrame": (OAServiceFrame, [("version","i32","never"),("service","string","never"),("method","string","never"),("arguments","json","never"),]),
    "OAServiceReply": (OAServiceReply, [("version","i32","never"),("service","string","never"),("method","string","never"),("ok","bool","never"),("payload","json","never"),]),
    "OAServiceError": (OAServiceError, [("code","string","never"),("message","string","never"),]),
    "OAResolverResolveResult": (OAResolverResolveResult, [("value","ResolveResult","never"),]),
}


class Resolver:
    __doc__ = "Common provider resolution vocabulary. Authorization comes from the receiving boundary, never from request fields. See RESOLUTION.md for selection and refusal semantics."
    def Resolve(self, request: "ResolveRequest") -> "ResolveResult":
        raise NotImplementedError


class ResolverClient(Resolver):
    def __init__(self, transport):
        self._transport = transport

    def Resolve(self, request: "ResolveRequest") -> "ResolveResult":
        _service_check("ResolveRequest", request)
        _oa_args = OAResolverResolveArguments()
        _oa_args.request = request
        _oa_arguments = _service_encode(enc_oaresolverresolvearguments, _oa_args, 1)
        _service_decode(_decode_oaresolverresolvearguments, _oa_arguments, 1)
        _oa_request = _service_request("abstraction.facade/resolver@1", "Resolve", _oa_arguments)
        _oa_payload = _service_response(self._transport.exchange_frame(_oa_request), "abstraction.facade/resolver@1", "Resolve")
        _oa_result = _service_decode(_decode_oaresolverresolveresult, _oa_payload, 1)
        return _oa_result.value
